'use strict'

const fs = require('node:fs')

const fsp = fs.promises

/**
 * 基于Linux cgroups v2 的资源限制。
 * 
 * 任何操作都要在/sys/fs/cgroup中进行
 * 
 * 创建资源组：
 * 
 * mkdir cf
 * 
 * cgroup.controllers	表示可以使用的资源控制，根cgroup内包含全部可用的资源控制，而子cgroup可以使用的控制继承自其父组的cgroup。
 * cgroup.subtree_control	表示当前已经启用的资源控制，其内容会继承到子cgroup的cgroup.controllers中。
 * 
 * 因为subtree_control的继承关系，需要确保在/sys/fs/cgroup/cgroup.subtree_control中必须要存在子组需要的项。
 * 
 * #启用对cpu memory的资源控制，+ 表示启用 - 表示不启用
 * echo '+cpu +memory +pids' > cgroup.subtree_control
 * 
 * 启用了pids，就可以把进程放在 cgroup.procs中进行管理
 * 
 * echo 1234 > cgroup.procs
 * echo 1256 >> cgroup.procs
 * 
 * 这表示CPU的10000个时间片，占用5000个，就是最大50%占有率。
 * echo 5000 10000 > cpu.max
 *
 * 对内存的限制，还需要设置memory.swap.max 和 memory.zswap.max
 * 否则内存超出限制会写入swap而不是终止进程。
 * 
 * 对内存的限制是整个组的限制，而不是单个进程。CPU的限制也是如此。
 * CPU会让整个cgroup中的进程分配总共的占比，这进行过严格测试。
 * 但是对内存的测试并不严格。
 */
//'domain threaded', 'domain invalid'
//以上在Linux 内核6.4.12上测试无效
//threaded模式开启后，不可以再变回domain
//threaded模式是针对线程的，也就是说如果cpu限制在

//domain模式会让每个线程均分CPU资源，而采用threaded模式就是每个线程占用CPU资源。

let allowType = [
  'domain', 'threaded'
]

class CGroup {

  constructor(cgdir) {

    this.cgdir = cgdir || '/sys/fs/cgroup'

    /**
     * 完整的信息请参考：
     * @link https://docs.kernel.org/admin-guide/cgroup-v2.html?highlight=admin+guide+cgroup+v2+rst
     * rbps  Max read bytes per second
     * wbps Max write bytes per second
     * riops Max read IO operations per second
     * wiops Max write IO operations per second
     * IO限制的格式：
     * 8:0 rbps=2097152 wbps=max riops=max wiops=120
     * 如果你去限制一个分区会报告没有这个设备，这个错误信息提示不准确。
     * 这种原因是因为linux只能对设备限制IO，不能对分区限制。
     * 从 /proc/partions获取分区信息，并得到设备的主设备号以及对应的表示设备的从设备号，这里是0。
     * 注意不要使用分区。
     * {
     *    [NAME] : {
     *      dirname: '',
     *      control: [
     *        'cpu', 'memory', 'pids'
     *      ],
     *      cpu: 50 | [3000, 10000],
     *      memory: 104857600
     *    }
     * }
     *
     * 单位说明（都跟 cgroup v2 的接口文件一致）：
     *   memory / swap  字节。104857600 = 100MB。小于 1000 会被当成误配并告警。
     *   cpu            数字按百分比（50 表示 50%），数组是 [quota, period] 微秒。
     *   pids           进程数上限，'max' 表示不限。
     *   rbps/wbps      字节每秒；riops/wiops 次每秒。
     */
    this.groupTable = {}

    this.defaultControl = ['cpuset', 'cpu', 'memory', 'pids', 'io']

    Object.defineProperty(this, 'allowType', {
      configurable: false,
      writable: false,
      enumerable: true,
      value: allowType
    })

    this.namePreg = /^[a-z][a-z0-9_\-]{1,100}$/i

    this.cpuset = {
      effective: null
    }

    this.getEffectiveCPU().then(res => {
      if (res.ok) {
        this.cpuset.effective = res.cpus
      }
    })
  }

  parseCPUS(data) {
    let cpus = []
    let cpumap = {}

    data.split(',').filter(p => p.length > 0).forEach(x => {
      if (x.indexOf('-') > 0) {
        let arr = x.split('-')
        let start = parseInt(arr[0])
        let end = parseInt(arr[1])
        for (let i = start; i <= end; i++) {
          if (!cpumap[`cpu_${i}`]) {
            cpumap[`cpu_${i}`] = true
            cpus.push(i)
          }
        }
      } else {
        if (!cpumap[`cpu_${x}`]) {
          cpumap[`cpu_${x}`] = true
          cpus.push(parseInt(x))
        }
      }
    })

    return cpus
  }

  async getEffectiveCPU(grp = '', cpufile='cpuset.cpus.effective') {
    try {
      let cpus_eft = this.cgdir + (grp ? '/' + grp : '') + '/' + cpufile
      await fsp.access(cpus_eft)
      //格式：0-3,5,6-9,12
      let data = await fsp.readFile(cpus_eft, {encoding: 'utf8'})
    
      return {
        ok: true,
        cpus: this.parseCPUS(data)
      }
    } catch (err) {
      return {
        ok: false,
        error: err
      }
    }
  }

  checkDetail(detail) {
    if (!detail.control || !Array.isArray(detail.control) || detail.control.length === 0) {
      if (!detail.control || typeof detail.control !== 'string') {
        detail.control = [...this.defaultControl]
      }
    }

    /**
     * 默认是domain、可以是 threaded、domain threaded、domain invalid
     * threaded模式在没有任何任务运行后，会变回domain模式，但是cgroup.type仍然是threaded
     */
    if (!detail.type || this.allowType.indexOf(detail.type) < 0) {
      detail.type = 'domain'
    }

    //maj min rbps wbps riops wiops
    if (!detail.io) detail.io = ''
    else if (typeof detail.io !== 'object') {
      detail.io = {}
    }
    
    if (detail.pids === 0 || detail.pids === 'max') {
      detail.pids = 'max'
    }
    else if (!detail.pids || typeof detail.pids !== 'number' || detail.pids < 0) {
      detail.pids = 'max'
    }

    /**
     * memory 单位是**字节**（对应 cgroup v2 的 memory.max）。
     *
     * 小于 1000 字节的限额没有任何现实意义，几乎一定是把单位记成了 KB/MB
     * （比如想写 100MB 结果写了 100）。这里仍然退回 'max' 保证不会把服务
     * 卡死，但**必须出声**：静默放开会让人以为限额生效了，实际完全没限制。
     */
    if (detail.memory !== 'max'
        && (!detail.memory || typeof detail.memory !== 'number' || detail.memory < 1000)
    ) {
      if (detail.memory) {
        console.error(`[cdpc-cgroup] memory=${detail.memory} 小于 1000 字节，已按不限制处理。`
          + `memory 的单位是字节，100MB 应写 ${100 * 1024 * 1024}。`)
      }
      detail.memory = 'max'
    }

    if (detail.swap === undefined) {
      detail.__swap__ = false
    } else {
      detail.__swap__ = true
    }

    if (detail.swap !== 'max' && (typeof detail.swap !== 'number' || detail.swap < 0)) {
      if (detail.memory === 'max')
        detail.swap = 'max'
      else detail.swap = 0
    }

    /**
     * cpu 支持两种写法：数字按百分比，数组是 [quota, period]（微秒）。
     *
     * 内核对 cpu.max 有硬约束（实测 5.15）：
     *   quota  >= 1000（或字面量 max）
     *   period ∈ [1000, 1000000]
     *
     * [FIX] 原来百分比换算成 `[pct * 100, 10000]`，于是**任何小于 10% 的配额
     * quota 都不足 1000**，内核 EINVAL 拒绝，create() 直接抛错。实测 cpu: 9 /
     * 5 / 1 全部失败，只有 >= 10 能用 —— 而文档里写的是"数字按百分比"，
     * 没有任何地方说下限是 10。
     *
     * 换成 `[pct * 1000, 100000]`：比值完全不变（50 还是 50%），但 1% 对应的
     * quota 正好是内核下限 1000，整个 1~99 区间都成立。100000µs 也正是
     * cgroup v2 的默认 period。
     */
    const CPU_MIN_QUOTA = 1000
    const CPU_MIN_PERIOD = 1000
    const CPU_MAX_PERIOD = 1000000

    /**
     * __cpu__ 记录用户是否显式指定过 cpu 限额：没指定时不该因为上级缺 cpu
     * 控制器而让整个建组失败（"只想限内存"是很常见的用法）。
     *
     * 数字分支必须排在「缺省兜底」之前判断，否则 `cpu: 0` 会被 `!detail.cpu`
     * 吃掉走进兜底分支拿到 95% —— 而 0 在 memory / pids / setCPU 里一律表示
     * 「不限制」，这里也必须一致。
     */
    detail.__cpu__ = (typeof detail.cpu === 'number' && !isNaN(detail.cpu))
                     || Array.isArray(detail.cpu)

    if (typeof detail.cpu === 'number' && !isNaN(detail.cpu)) {
      if (detail.cpu >= 100 || detail.cpu <= 0) {
        detail.cpu = 0                       // 0 表示不限制，create() 写 max
      } else {
        let quota = Math.round(detail.cpu * 1000)

        if (quota < CPU_MIN_QUOTA) {
          console.error(`[cdpc-cgroup] cpu=${detail.cpu}% 换算出的 quota ${quota}µs `
            + `低于内核下限 ${CPU_MIN_QUOTA}µs，已按 ${CPU_MIN_QUOTA}µs（约 `
            + `${(CPU_MIN_QUOTA / 1000).toFixed(1)}%）处理。`)
          quota = CPU_MIN_QUOTA
        }

        detail.cpu = [quota, 100000]
      }
    } else if (Array.isArray(detail.cpu)) {
      // 数组形态：内核约束提前挡住，否则会在写 cpu.max 时才抛 EINVAL
      let q = detail.cpu[0]
      let pd = detail.cpu[1]

      if (typeof q !== 'number' || typeof pd !== 'number' || isNaN(q) || isNaN(pd)
          || pd < CPU_MIN_PERIOD || pd > CPU_MAX_PERIOD
          || (q !== 0 && q < CPU_MIN_QUOTA))
      {
        console.error(`[cdpc-cgroup] cpu=[${q}, ${pd}] 不满足内核约束`
          + `（quota >= ${CPU_MIN_QUOTA}，period ∈ [${CPU_MIN_PERIOD}, ${CPU_MAX_PERIOD}]，`
          + `单位微秒），已按不限制处理。`)
        detail.__cpu__ = false
        detail.cpu = 0
      } else if (q === 0) {
        detail.cpu = 0                       // 显式写 0 配额等同于不限制
      }
    } else {
      /**
       * 完全没写、或写了个非数字非数组的东西 → **不限制**。
       *
       * 早先这里兜的是 `[9500, 10000]`，但那是 **0.95 个 CPU**（不是"95% 的
       * 机器"）：实测 2 核机器上该组里两个忙进程只拿到 0.97 个 CPU、累计被
       * 限流 3.75 秒；核数越多这个坑越深（16 核上等于被限到全机的 6%）。
       * 也就是说，只想限内存的配置会莫名其妙地被砍掉 CPU。
       *
       * cdpc 是库，没被要求限制就应该**跟系统默认走** —— `memory` 与 `pids`
       * 的缺省都是 'max'，cpu 是唯一的例外，现在拉齐。
       * 需要为了稳定性做兜底收敛的是上层（cdpcmd 的预设组全部显式写了 cpu）。
       */
      detail.__cpu__ = false
      detail.cpu = 0
    }

    //有效CPU范围，解析出来后从
    detail.cpuset = {
      effective: null
    }

  }

  parseCPULimit(detail) {
    if (!detail.cpus || !detail.cpuset || !detail.cpuset.effective) return ''

    let cpus = detail.cpus

    let elength = detail.cpuset.effective.length
    let ecpus = detail.cpuset.effective

    if (elength === 1) return ''

    if (cpus[0] === '%') {
      let cp, pos = 'rand'

      if (['-', '+', '='].indexOf(cpus[cpus.length - 1]) >= 0) {
        cp = parseInt(cpus.substring(1, cpus.length - 1))
        pos = cpus[cpus.length - 1]
      } else {
        cp = parseInt(cpus.substring(1))
      }
      
      if (isNaN(cp)) return ''

      if (cp <= 0 || cp >= 100) return ''

      cp = cp / 100

      let ind = 0
      switch (pos) {
        case 'rand':
          ind = parseInt(Math.random() * (elength - elength * cp))
          return ecpus.slice(ind, parseInt(elength * cp) + ind)
          break
        
        case '=':
          ind = parseInt(elength / 2) - parseInt(elength * cp / 2)
          return ecpus.slice(ind, ind + parseInt(elength * cp + 0.5))
          break

        case '-':
          ind = 0
          return ecpus.slice(ind, parseInt(elength * cp + 0.2))
          break

        case '+':
          let total = parseInt(elength * cp + 0.1)
          let real_cpus = []
          let count = 0
          for (let i = elength-1; i >= 0; i--) {
            real_cpus.push(ecpus[i])
            count++
            if (count >= total) break
          }

          return real_cpus.sort((a,b) => {
            return a-b
          })
      }
      
    }

    return cpus
  }

  async setType(name, typ) {
    if (this.allowType.indexOf(typ) < 0) return false
    
    let grp_path = this.findPath(name)
    if (!grp_path) return false

    return await fsp.writeFile(grp_path + '/cgroup.type', typ)
                    .then(r => {
                      this.groupTable[name].type = typ
                      return true
                    })
                    .catch(err => {
                      return false
                    })
  }

  async create(name, detail) {
    if (!this.namePreg.test(name)) {
      throw new Error(`${name} 不符合要求，要求：字母开头，支持字母、数字、下划线、连字符（减号），长度2～101。`)
    }

    this.checkDetail(detail)

    this.groupTable[name] = detail

    let cgrp_subtree_control = this.cgdir + '/cgroup.subtree_control'

    let context = await fsp.readFile(cgrp_subtree_control, {encoding: 'utf8'})

    let carr = context.split(/\s+/).filter(p => p.length > 0)

    /**
     * 只能启用**本 cgroup 实际可用**的控制器。
     *
     * cgroup.controllers 列出上级委托下来的控制器；往 subtree_control 写一个
     * 不在其中的控制器，内核返回的是 **ENOENT**（不是 EINVAL），于是 create()
     * 抛出一个既不说文件也不说原因的 `ENOENT: ... write`。
     *
     * 现实场景：cdpcd 跑在 systemd 服务里（unit 带 Delegate=yes）时控制器是齐的；
     * 手工在登录会话里直接跑 cdpcd 时，session scope 的 cgroup.controllers 往往
     * 只有 "memory pids"，于是 9 个预设组全部创建失败 —— 而以前这个失败既没人
     * 记录也看不出根因。
     */
    let available = []
    try {
      let ctlText = await fsp.readFile(this.cgdir + '/cgroup.controllers', {encoding: 'utf8'})
      available = ctlText.split(/\s+/).filter(p => p.length > 0)
    } catch (err) {
      available = this.defaultControl.slice()   // 读不到就按原行为全试
    }

    let want = this.defaultControl.filter(x => available.indexOf(x) >= 0)
    let missing = this.defaultControl.filter(x => available.indexOf(x) < 0)

    let add_controllers = []
    for (let x of want) {
      if (carr.indexOf(x) < 0) {
        add_controllers.push('+' + x)
      }
    }

    if (add_controllers.length > 0) {
      try {
        await fsp.writeFile(cgrp_subtree_control, add_controllers.join(' '), {flag: 'a'})
      } catch (err) {
        throw new Error(`在 ${this.cgdir} 启用控制器 ${add_controllers.join(' ')} 失败`
          + `（${err.code || err.message}）。该 cgroup 可用的控制器：`
          + `"${available.join(' ') || '(无)'}"。`)
      }
    }

    // 需要但拿不到的控制器：直接说清楚，否则后面写接口文件只会抛裸 ENOENT
    let needed = []
    if (detail.memory !== 'max' && missing.indexOf('memory') >= 0) needed.push('memory')
    if (detail.__cpu__ && Array.isArray(detail.cpu) && missing.indexOf('cpu') >= 0) needed.push('cpu')
    if (detail.pids !== 'max' && missing.indexOf('pids') >= 0) needed.push('pids')
    if (detail.cpus && missing.indexOf('cpuset') >= 0) needed.push('cpuset')

    if (needed.length > 0) {
      throw new Error(`${name}: 上级 cgroup ${this.cgdir} 没有委托 `
        + `${needed.join(' / ')} 控制器（可用：${available.join(' ') || '(无)'}），`
        + `这些限额无法生效。cdpcd 需要跑在带 Delegate=yes 的 systemd 服务里，`
        + `或把 cgroupBaseDir 指到一个已委托对应控制器的 cgroup。`)
    }
    
    let cgrpdir = this.cgdir + '/' + name

    try {
      await fsp.access(cgrpdir)
    } catch (err) {
      await fsp.mkdir(cgrpdir)
    }

    try {
      let cur_type = await fsp.readFile(cgrpdir + '/cgroup.type', {encoding: 'utf8'})
      if (cur_type !== 'threaded' && cur_type !== detail.type) {
        await this.setType(name, detail.type)
      }
    } catch (err) {}

    /**
     * 写接口文件时把裸 ENOENT 翻译成人能看懂的原因。
     *
     * cgroup v2 里子组只会出现**上级 subtree_control 已启用**的控制器对应的
     * 接口文件。cdpcd 跑在 systemd 服务里（unit 有 Delegate=yes）时控制器是
     * 齐的；但如果 cgroupBaseDir 落在一个没委托控制器的 cgroup 上（比如手工
     * 在登录会话里直接跑 cdpcd，session scope 的 subtree_control 是空的），
     * 这里只会抛一个 `ENOENT: no such file or directory, write`，既不说是哪个
     * 文件也不说为什么 —— 排查成本极高。
     */
    const writeCtl = async (file, value) => {
      try {
        await fsp.writeFile(`${cgrpdir}/${file}`, `${value}`)
      } catch (err) {
        if (err.code !== 'ENOENT') throw err

        let ctl = ''
        try {
          ctl = (await fsp.readFile(cgrp_subtree_control, {encoding: 'utf8'})).trim()
        } catch (e) {}

        throw new Error(`${cgrpdir}/${file} 不存在：对应的控制器没有被上级 cgroup 委托。`
          + `上级 ${this.cgdir} 的 subtree_control = "${ctl || '(空)'}"。`
          + `cdpcd 需要跑在带 Delegate=yes 的 systemd 服务里，`
          + `或把 cgroupBaseDir 指到一个已委托控制器的 cgroup。`)
      }
    }

    /**
     * cpu.max 的写入条件。
     *
     * [FIX] 原来只在 `Array.isArray(detail.cpu)` 时才写，于是 `cpu: 0`（不限制）
     * 这条路**什么都不写** —— 在已存在的目录上重建时，上一次的配额就留在那儿了。
     * 实测：先 cpu:50 建组，再改成 cpu:0 重建，cpu.max 仍是 `50000 100000`，
     * 用户以为解除了限制其实没解除。memory 和 pids 没这个问题，因为它们的
     * "不限制"是 'max'，是个真的会被写下去的值。所以这里也要显式写 `max`。
     *
     * 上级没委托 cpu 控制器时跳过：用户没显式要求 cpu 限额（checkDetail 兜的
     * 95% 默认值）不该让「只想限内存」的配置整个失败；显式要求过的已经在前面
     * 的 needed 检查里拦下了。
     */
    if (missing.indexOf('cpu') < 0) {
      await writeCtl('cpu.max',
        Array.isArray(detail.cpu) ? `${detail.cpu[0]} ${detail.cpu[1]}` : 'max 100000')
    }

    if (detail.memory && detail.type === 'domain') {
      await writeCtl('memory.max', detail.memory)

      if (detail.memory !== 'max') {
        await this.setSwap(name, detail.__swap__ ? detail.swap : 0)
      }
    }

    await this.setIO(name, detail.io)
    await this.setPids(name, detail.pids)

    if (detail.control.indexOf('cpuset') >= 0) {
      let cpu_eft = await this.getEffectiveCPU(detail.name)
      if (cpu_eft.ok) {
        detail.cpuset.effective = cpu_eft.cpus
      }
    }

    /**
     * 尽可能动态支持：
     *  百分比自动确定：%50 %80, %50- %50+ %20=
     *      - 表示前50%，+表示后50% =表示从中间开始
     *      默认是随机处理。
     *  指定：0-1,2
     */
    if (detail.cpus && typeof detail.cpus !== 'string') {
      detail.cpus = ''
    }

    if (detail.cpus) {
      await this.setCPUSet(name, detail.cpus)
    }
  }

  findPath(name) {
    let cgrp = this.groupTable[name]
    if (!cgrp) return false
    return this.cgdir + '/' + name
  }

  /**
   * 删除资源组：直接 rmdir，不需要任何提权（空组谁建的谁就能删）。
   *
   * 组内还有任务时内核返回 EBUSY：组正被使用、本就不该删，按「跳过」处理，
   * 不算失败也不需要引用计数或跨进程协调——任务一退即可删。
   *
   * 注意 EBUSY 有两种成因，这里不做区分（也区分不出来）：组内确实还有任务，
   * 或任务已退但内核仍在异步离线该组。后者稍后重试即可删。
   *
   * 返回值统一为对象：`{ok:false, message}` 表示没删成，
   * `{ok:true, skipped:true}` 表示按跳过处理，调用方用 `res.ok` 判即可。
   */
  async remove(name) {
    let cgrp = this.groupTable[name]
    if (!cgrp) return {ok: false, message: `cgroup「${name}」未创建（需先调用 create）`}

    try {
      await fsp.rmdir(this.cgdir + '/' + name)
    } catch (err) {
      if (err.code === 'EBUSY' || err.code === 'ENOTEMPTY')
        return {ok: true, skipped: true, message: `组内有任务（${err.code}），保留`}

      if (err.code === 'ENOENT') {
        delete this.groupTable[name]
        return {ok: true}
      }

      return {ok: false, message: `rmdir 失败: ${err.code || err.message}`}
    }

    // 只有目录真的删掉了才出表：EBUSY 跳过时组还在盘上被用着，
    // 出表会让后续调用拿到 false，表现成「组不存在」的假象
    delete this.groupTable[name]

    return {ok: true}
  }

  fmtIO(iobj) {
    if (iobj.maj === undefined) return ''

    let iostr_arr = []

    ;['rbps', 'wbps', 'riops', 'wiops'].forEach(x => {
      if (iobj[x]) {
        iostr_arr.push(`${x}=${iobj[x]}`)
      }
    })

    if (iostr_arr.length === 0) return ''

    return `${iobj.maj}:${iobj.min || 0} ${iostr_arr.join(' ')}`
  }

  async setCPUSet(name, cpus) {
    let cgrp = this.groupTable[name]
    if (!cgrp) return false

    cgrp.__cpus__ = cpus
    let real_cpus = this.parseCPULimit(cgrp)

    cgrp.cpus = Array.isArray(real_cpus) ? real_cpus.join(',') : real_cpus

    if (cgrp.cpus) {
      try {
        let cpusetfile = this.cgdir + '/' + name + '/cpuset.cpus'
        await fsp.access(cpusetfile)
        await fsp.writeFile(cpusetfile, cgrp.cpus, {encoding:'utf8'})
      } catch (err) {
        return false
      }
    }

    return true
  }

  async setPids(name, pid_max) {
    let cgrp = this.groupTable[name]
    if (!cgrp) return false

    if (!pid_max || (pid_max !== 'max' && typeof pid_max !== 'number') ) {
      return false
    }

    try {
      await fsp.writeFile(this.cgdir + '/' + name + '/pids.max', `${pid_max}`)
      cgrp.pids = pid_max
      return true
    } catch (err) {
      console.error(err)
      return false
    }

  }

  async setIO(name, iobj) {
    if (!iobj || typeof iobj !== 'object') return false
    
    let cgrp = this.groupTable[name]
    if (!cgrp) return false

    let iostr = this.fmtIO(iobj)
    if (!iostr) return false

    try {
      await fsp.writeFile(this.cgdir + '/' + name + '/io.max', iostr)
      cgrp.io = iobj
      return true
    } catch (err) {
      console.error(err)
      return false
    }
  }

  /**
   * 设置 CPU 配额，写入 cgroup v2 的 cpu.max（格式：`<quota> <period>`，单位微秒）。
   *
   * 两种入参形态，与 create() 的 detail.cpu 保持一致：
   *   - 数组 [quota, period]：直接写，例 [50000, 100000] 表示 50%
   *   - 数字（百分比）：按 checkDetail 里同样的规则换算成 [pct * 100, 10000]
   *     0 或 >= 100 视为不限制，写 'max 100000'
   *
   * [FIX] 原代码有两个问题：
   *   1. `detail.cpu = cpu` 里的 `detail` 在此作用域**未定义**，必然抛
   *      ReferenceError 被 catch 吞掉 —— cpu.max 其实写成功了，函数却返回
   *      false 且 groupTable 不同步，调用方据此判断会完全反了。
   *   2. 数字形态没有换算成数组就去取 cpu[0]/cpu[1]，写进去的是
   *      "undefined undefined"，内核 EINVAL 拒绝，等于静默失效。
   */
  async setCPU(name, cpu) {
    if (!cpu && typeof cpu !== 'number') return false

    let cgrp = this.groupTable[name]
    if (!cgrp) return false

    let quota = ''
    let period = 10000

    if (Array.isArray(cpu)) {
      // 内核约束：quota >= 1000（0 视为不限制），period ∈ [1000, 1000000]，单位微秒
      if (cpu.length < 2
          || typeof cpu[0] !== 'number' || typeof cpu[1] !== 'number'
          || isNaN(cpu[0]) || isNaN(cpu[1])
          || cpu[1] < 1000 || cpu[1] > 1000000
          || (cpu[0] !== 0 && cpu[0] < 1000)) {
        console.error(`[cdpc-cgroup] setCPU(${name}, [${cpu[0]}, ${cpu[1]}]) 不满足内核约束`
          + `（quota >= 1000，period ∈ [1000, 1000000]，单位微秒）。`)
        return false
      }

      quota = cpu[0] === 0 ? 'max' : String(cpu[0])
      period = cpu[1]
    } else if (typeof cpu === 'number') {
      if (isNaN(cpu) || cpu < 0) return false

      if (cpu === 0 || cpu >= 100) {
        // 不限制：cpu.max 用 'max' 表示无配额
        quota = 'max'
        period = 100000
      } else {
        // 与 checkDetail 保持同一套换算：period 用 100000，1% 正好是内核下限
        let q = Math.round(cpu * 1000)
        if (q < 1000) q = 1000
        quota = String(q)
        period = 100000
      }
    } else {
      return false
    }

    try {
      await fsp.writeFile(this.cgdir + '/' + name + '/cpu.max', `${quota} ${period}`)
      cgrp.cpu = (quota === 'max') ? 0 : [parseInt(quota, 10), period]
      return true
    } catch (err) {
      console.error(err)
      return false
    }
  }

  /**
   * 设置 swap 上限。单位与 memory.swap.max 一致：**字节**（或 'max'）。
   *
   * [FIX] 原代码写入的是 `cgrp.swap`（**改之前的旧值**），改完才把新值存进表，
   * 于是每次调用都落后一拍：第一次调用等于没改，第二次才把第一次的值写进去。
   * 实测：setMem 改 128MB → memory.max 仍是 64MB；再改 256MB → 变成 128MB。
   */
  async setSwap(name, mem) {
    let cgrp = this.groupTable[name]
    if (!cgrp) return false

    if (mem !== 'max' && (typeof mem !== 'number' || isNaN(mem) || mem < 0)) {
      return false
    }

    try {
      await fsp.writeFile(this.cgdir + '/' + name + '/memory.swap.max', `${mem}`)
      cgrp.swap = mem
      let zswap_file = this.cgdir + '/' + name + '/memory.zswap.max'
      // memory.zswap.max 是 5.19+ 才有的文件，用 access 探测后再写（老内核直接跳过）
      await fsp.access(zswap_file)
        .then(async res => {
          return await fsp.writeFile(zswap_file, `${mem}`)
        })
        .catch(err => {})

      return true
    } catch (err) {
      console.error(err)
      return false
    }
  }

  /**
   * 设置内存上限。单位与 cgroup v2 的 memory.max 一致：**字节**（或 'max'）。
   *
   * 注意 cdpc 里有两套内存单位，不要混：
   *   - 这里（cgroup）是 **字节**，由内核强制执行，超了直接 OOM kill；
   *   - 服务配置的 limit.maxrss 是 **KB**，由 cdpc 自己轮询判定后重启/停止。
   *
   * [FIX] 原代码写入 `cgrp.memory`（旧值），同 setSwap 的落后一拍问题。
   */
  async setMem(name, mem, setSwap=true) {
    if (!mem && typeof mem !== 'number') return false

    if (mem !== 'max' && (typeof mem !== 'number' || isNaN(mem))) return false

    if (mem !== 'max' && mem <= 0) mem = 'max'

    let cgrp = this.groupTable[name]
    if (!cgrp) return false

    //线程模式，没有memory.max文件
    if (cgrp.type !== 'domain') return false

    if (mem !== 'max' && setSwap) {
      await this.setSwap(name, 0)
    }

    try {
      await fsp.writeFile(this.cgdir + '/' + name + '/memory.max', `${mem}`)
      cgrp.memory = mem
      return true
    } catch (err) {
      console.error(err)
      return false
    }
  }

  /**
   * 把进程移入 cgroup。返回 {ok, message}：失败原因必须能传回调用方，
   * 否则「服务配了 cgroup 但实际没受限」这种情况完全无法定位。
   */
  async addPids(name, pids) {
    if (typeof pids === 'number') pids = [pids]

    if (!Array.isArray(pids)) return {ok: false, message: 'pids 不是数组或数字'}

    let realPids = []

    pids.forEach(p => {
      if (typeof p === 'number' && p > 1) {
        realPids.push(p)
      }
    })

    if (realPids.length <= 0) return {ok: false, message: '没有合法的 pid'}

    let cgrp = this.groupTable[name]
    if (!cgrp) return {ok: false, message: `cgroup「${name}」未创建（需先调用 create）`}

    try {
      await fsp.writeFile(this.cgdir + '/' + name + '/cgroup.procs', realPids.join('\n'), {flag: 'a'})
    } catch (err) {
      return {ok: false, message: `写入 cgroup.procs 失败: ${err.code || err.message}`}
    }

    return {ok: true}
  }

}

/**
 * 在 base 上做一次真实探测：确保基启用了所需子控制器 → mkdir 探针组 →
 * 写限额 → 回读核对 → rmdir。
 *
 * 不靠 access 权限位猜——access 说「可写」不代表接口文件真的能写，
 * 只有一次完整的写入与回读才算证据。
 *
 * 探针组是 base 的子组，它的限额接口文件只在 base 的 subtree_control 启用了对应
 * 控制器之后才会出现（新建空组的 subtree_control 是空的）。所以探测前必须先按
 * create() 的同一口径补齐缺口，否则会把「可用但还没启用」误判成「不可用」：
 * 这时写接口文件得到的是 EACCES（文件不存在），而不是 ENOENT。
 *
 * @returns {object} 探测结果（复用传入的 result 容器，补充探测细节）
 */
async function probeBase(base, needed, result) {
  // 随机后缀：同进程的多个实例并发探测同一基路径时，固定名字会让
  // 「清理残留」的 rmdir 删掉对方正在使用的活探针
  let probe = `${base}/cdpc-probe-${process.pid}-${Math.random().toString(36).slice(2, 8)}`

  let controllers = []
  try {
    controllers = (await fsp.readFile(`${base}/cgroup.controllers`, 'utf8'))
      .trim().split(/\s+/).filter(Boolean)
  } catch (err) {
    result.reason = `${base}: 读 cgroup.controllers 失败（${err.code || err.message}）`
    return result
  }

  let missing = needed.filter(c => controllers.indexOf(c) < 0)

  // 无论成败都回填：cgroupProbe() 是结构化出口，不能只在成功时有内容
  result.controllers = controllers
  result.missing = missing

  if (missing.length > 0) {
    result.reason = `${base}: 委派下来的控制器为 "${controllers.join(' ') || '(无)'}"，`
      + `缺 ${missing.join('/')}`
    return result
  }

  /**
   * 补齐基的子控制器缺口。
   *
   * 自动分支传进来的是 cdpc 自建的专用空基（cdpc.scope），needed 整个就是 gap，
   * 写的只有这个基自己的开关；委派边界从头到尾只读，不碰它的 subtree_control。
   * 显式分支传进来的是用户指定的目录，已启用时 gap 为空、一个字节都不写。
   */
  try {
    let on = (await fsp.readFile(`${base}/cgroup.subtree_control`, 'utf8'))
      .trim().split(/\s+/).filter(Boolean)
    let gap = needed.filter(c => on.indexOf(c) < 0)

    if (gap.length > 0) {
      await fsp.writeFile(`${base}/cgroup.subtree_control`,
        gap.map(c => '+' + c).join(' '), {flag: 'a'})
    }
  } catch (err) {
    // EBUSY/EACCES 基本都是「这个目录不是 cdpc 专用的空 cgroup」：里面有进程时
    // 内核不允许启用子控制器。不点破就会被读成「没权限，得用 root」。
    result.reason = `${base}: 在 subtree_control 启用 ${needed.map(c => '+' + c).join(' ')} `
      + `失败（${err.code || err.message}）。cgroupBaseDir 必须指向 cdpc 专用的空 `
      + `cgroup：目录内有进程时内核不允许启用子控制器，且会影响同层兄弟组。`
    return result
  }

  try {
    await fsp.mkdir(probe)
  } catch (err) {
    result.reason = `${base}: 建探针组失败（${err.code || err.message}）`
    return result
  }

  try {
    // cpu.max 取 max 表示不设配额，只是验证接口文件写得进去、读得回来
    const writes = [
      ['cpu.max', 'max 100000', 'cpu'],
      ['memory.max', '1048576', 'memory'],
      ['pids.max', '50', 'pids']
    ]

    for (let [file, val, ctl] of writes) {
      if (needed.indexOf(ctl) < 0) continue

      let path = `${probe}/${file}`

      // 上面已确保 needed 全部启用，探针组里必有该文件；缺文件说明接口文件与
      // 控制器名单不一致，属真异常，必须判死而不是跳过
      await fsp.writeFile(path, val)

      let back = (await fsp.readFile(path, 'utf8')).trim()
      if (back !== val) {
        result.reason = `${base}: ${file} 写入 ${val} 回读到 ${back}，不可信`
        return result
      }
    }
  } catch (err) {
    result.reason = `${base}: 写限额失败（${err.code || err.message}）`
    return result
  } finally {
    // 探针组无进程，rmdir 不会 EBUSY；失败也先清干净再报错
    try { await fsp.rmdir(probe) } catch (err) {}
  }

  return Object.assign(result, {
    supported: true,
    base,
    boundary: base,
    controllers,
    missing: [],
    reason: '',
    probed: true
  })
}

/**
 * root 下的基准目录校验：只读、同步、零副作用。
 *
 * 「我是 root」不等于「这个路径能干活」——cgroup v1、cgdir 不存在、控制器没
 * 委派，root 一样写不动限额文件。这里把能靠只读判出来的部分判掉，让
 * cgroupProbe().supported 在 root 下也是实测结论而不是身份推定。
 *
 * 刻意不做探针（mkdir/写/回读）：那会给 root 的启动路径新增从未有过的副作用，
 * 而 root 的实际能力由 create() 自己保证（它本就会启用所需控制器并抛出确切错误）。
 * 结论强度用 probed:false 标明，与 resolveCgroupBase 的写入自证区分开。
 *
 * @param {string} cgdir 基准目录
 * @param {string[]} needed 需要的控制器
 * @returns {object} 与 resolveCgroupBase 同结构，额外带 probed 标记
 */
CGroup.checkBase = function (cgdir, needed) {
  let result = {
    supported: false, base: '', boundary: '',
    controllers: [], missing: [], reason: '', tried: [], probed: false
  }

  let controllers = []
  try {
    controllers = fs.readFileSync(`${cgdir}/cgroup.controllers`, {encoding: 'utf8'})
      .trim().split(/\s+/).filter(Boolean)
  } catch (err) {
    result.reason = `${cgdir}: 读 cgroup.controllers 失败（${err.code || err.message}）。`
      + '不是 cgroup v2 层级，或该目录不存在。'
    return result
  }

  let subtree = ''
  try {
    subtree = fs.readFileSync(`${cgdir}/cgroup.subtree_control`, {encoding: 'utf8'}).trim()
  } catch (err) {}

  result.controllers = controllers
  result.missing = needed.filter(c => controllers.indexOf(c) < 0)
  result.tried.push({path: cgdir, subtree_control: subtree, missing: result.missing})

  if (result.missing.length > 0) {
    result.reason = `${cgdir}: 可用的控制器为 "${controllers.join(' ') || '(无)'}"，`
      + `缺 ${result.missing.join('/')}`
    return result
  }

  // 目录写不动（只读挂载等）——到这一步 create() 也必然失败
  try {
    fs.accessSync(cgdir, fs.constants.W_OK)
  } catch (err) {
    result.reason = `${cgdir}: 不可写（${err.code || err.message}）`
    return result
  }

  result.supported = true
  result.base = cgdir
  result.boundary = cgdir
  result.missing = []
  result.reason = ''

  return result
}

/**
 * 非 root 下的 cgroup 基路径解析：用能力探测取代 geteuid 身份判定。
 *
 * 判据不是「我是谁」，而是「这个路径能不能建组、能不能写限额、写完能不能回读到」：
 *   1) 显式 baseDir → 直接探测它（保持原有能力，基就是它本身）；
 *   2) 否则从 /proc/self/cgroup 取自身相对路径（必须剥 0:: 前缀——
 *      按 split(':')[1] 取到的是空串，会误判成「环境不支持」），
 *      从最近的父级逐级向上，找第一个 cgroup.subtree_control 已包含全部所需
 *      控制器的祖先作为委派边界（判「委派边界」不能只看可写性：systemd 管理的
 *      中间层往往可写，但在它身上开控制器会与 systemd 的管理打架）；
 *      基落在边界下的专用空子组 cdpc.scope，探针就在**这个基上**做——
 *      探的就是用的，不留「边界能写所以基也能写」的推断缺口，边界自身只读。
 *   全都不满足 → supported:false，reason 列出实际找过哪些路径、各缺什么，
 *   missing 是这些层里出现过的缺口并集（可直接据此提委派）。
 *
 * 绝不使用 user-<uid>.slice/user@<uid>.service 这类拼出来的固定路径：
 * 委派边界可能比 user 服务更深一层（如 …/app.slice/app-XXX.scope 的父级）。
 *
 * @param {object} opts
 * @param {string} [opts.baseDir] 显式指定的基路径
 * @param {string[]} [opts.controllers] 需要的控制器，默认 ['cpu','memory','pids']
 * @returns {Promise<object>} {supported, base, boundary, controllers, missing, reason, tried}
 */
CGroup.resolveCgroupBase = async function (opts = {}) {
  let needed = Array.isArray(opts.controllers) && opts.controllers.length > 0
    ? opts.controllers : ['cpu', 'memory', 'pids']

  let result = {
    supported: false, base: '', boundary: '',
    controllers: [], missing: [], reason: '', tried: [], probed: false
  }

  // 显式指定：只探测，不再向上找
  if (opts.baseDir) {
    result.boundary = opts.baseDir
    return await probeBase(opts.baseDir, needed, result)
  }

  // 自身所在 cgroup（v2 统一层级，唯一 0:: 行）
  let selfPath = ''
  try {
    let lines = (await fsp.readFile('/proc/self/cgroup', 'utf8')).split('\n')
    selfPath = (lines.find(l => l.indexOf('0::') === 0) || '').replace(/^0::/, '')
  } catch (err) {}

  if (!selfPath || selfPath === '/') {
    result.reason = '无法从 /proc/self/cgroup 取得自身 cgroup 路径'
      + (selfPath === '/' ? '（进程已在层级根部）' : '')
    return result
  }

  // 从最近的父级向上走（自身组内有进程，不能当基：no-internal-processs 规则）
  let parts = selfPath.split('/').filter(Boolean)
  let reasons = []

  // 各层出现过的控制器缺口并集：supported:false 时给 cgroupProbe() 结构化消费，
  // 免得调用方只能去正则匹配中文诊断
  let gaps = []

  for (let i = parts.length - 1; i >= 0; i--) {
    let cand = '/' + parts.slice(0, i).join('/')
    let dir = `/sys/fs/cgroup${cand === '/' ? '' : cand}`
    let ctl = ''

    try {
      ctl = (await fsp.readFile(`${dir}/cgroup.subtree_control`, 'utf8')).trim()
    } catch (err) {
      reasons.push(`${cand}: 读 subtree_control 失败（${err.code || err.message}）`)
      continue
    }

    let have = ctl.split(/\s+/).filter(Boolean)
    let missing = needed.filter(c => have.indexOf(c) < 0)
    result.tried.push({path: cand, subtree_control: ctl, missing})

    for (let c of missing) {
      if (gaps.indexOf(c) < 0) gaps.push(c)
    }

    if (missing.length > 0) {
      reasons.push(`${cand}: subtree_control="${ctl || '(空)'}"，缺 ${missing.join('/')}`)
      continue
    }

    /**
     * 基落在边界下的专用空子组，探针就在这个基上做——「探的就是用的」。
     *
     * 边界自身一个字节都不写：它的 subtree_control 已含全部 needed（上面刚筛过），
     * 需要补开关的是基自己的 subtree_control（新建的空组这里是空的），
     * probeBase 补的正是 create() 以后要做的那一步。
     */
    let base = `${dir}/cdpc.scope`
    let created = false

    try {
      await fsp.mkdir(base)   // 已存在（上次运行建的）时 EEXIST，复用即可
      created = true
    } catch (err) {
      if (err.code !== 'EEXIST') {
        reasons.push(`${cand}: 建 cdpc.scope 失败（${err.code || err.message}）`)
        continue
      }
    }

    let probed = await probeBase(base, needed, result)

    if (probed.supported) {
      probed.boundary = dir
      return probed
    }

    // 探测不通过就把自己刚建的空组收掉，别挡住继续向上找
    if (created) {
      try { await fsp.rmdir(base) } catch (err) {}
    }

    reasons.push(`${cand}: ${probed.reason}`)
  }

  // 没进过 probeBase（各层都在 subtree_control 就被拒）时它没机会回填，这里统一收口
  result.missing = gaps
  result.reason = '没有找到可用的委派 cgroup 子树。' + reasons.join('；')
  return result
}

module.exports = CGroup
